-- Generated FCPS-1 Surgery Part 4 MCQ import (3000 rows).
create temporary table if not exists fcps_mcq_stage (
  id uuid primary key, subject_name text not null, chapter_name text not null,
  question text not null, options jsonb not null, correct_answer text not null, explanation text not null
) on commit drop;


select x.id, x.question, x.options, x.correct_answer, x.explanation, 'fcps1_surgery_allied_2026', c.id, s.name, 'FCPS Part 1'
from fcps_mcq_stage x
join public.subjects s on lower(s.name)=lower(x.subject_name)
join public.chapters c on c.subject_id=s.id and lower(c.name)=lower(x.chapter_name)
where s.year='surgery_allied' and s.institutes=to_jsonb(array['fcps_part_1']::text[])
on conflict (id) do update set
  question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer,
  explanation=excluded.explanation, category=excluded.category, chapter_id=excluded.chapter_id,
  subject=excluded.subject, difficulty=excluded.difficulty;

truncate table fcps_mcq_stage;
